import{_ as l,C as c,o as a,c as u,a2 as o,b as i,w as e,a as d,E as n,a3 as s}from"./chunks/framework.CgxQ0r6v.js";const E=JSON.parse('{"title":"Manual de Estudio Profundo: Evaluación 4","description":"","frontmatter":{},"headers":[],"relativePath":"materias/Edumatica/documentacion/IV-XII/Lectura_Catedra_Evaluacion_4.md","filePath":"materias/Edumatica/documentacion/IV-XII/Lectura_Catedra_Evaluacion_4.md"}'),p={name:"materias/Edumatica/documentacion/IV-XII/Lectura_Catedra_Evaluacion_4.md"};function m(g,t,f,h,A,b){const r=c("Mermaid");return a(),u("div",null,[t[4]||(t[4]=o('<h1 id="manual-de-estudio-profundo-evaluacion-4" tabindex="-1">Manual de Estudio Profundo: Evaluación 4 <a class="header-anchor" href="#manual-de-estudio-profundo-evaluacion-4" aria-label="Permalink to &quot;Manual de Estudio Profundo: Evaluación 4&quot;">​</a></h1><h2 id="materia-edumatica" tabindex="-1">Materia: EduMática <a class="header-anchor" href="#materia-edumatica" aria-label="Permalink to &quot;Materia: EduMática&quot;">​</a></h2><h3 id="eje-tematico-software-educativo-—-diseno-desarrollo-y-prototipado" tabindex="-1">Eje Temático: Software Educativo — Diseño, Desarrollo y Prototipado <a class="header-anchor" href="#eje-tematico-software-educativo-—-diseno-desarrollo-y-prototipado" aria-label="Permalink to &quot;Eje Temático: Software Educativo — Diseño, Desarrollo y Prototipado&quot;">​</a></h3><hr><h2 id="🧭-introduccion-cuando-el-codigo-se-convierte-en-maestro" tabindex="-1">🧭 Introducción: Cuando el Código se Convierte en Maestro <a class="header-anchor" href="#🧭-introduccion-cuando-el-codigo-se-convierte-en-maestro" aria-label="Permalink to &quot;🧭 Introducción: Cuando el Código se Convierte en Maestro&quot;">​</a></h2><p>Hemos recorrido un largo camino. En la Evaluación 1 aprendimos las teorías que explican cómo el ser humano aprende. En la Evaluación 2 practicamos la ejecución de una clase real como docentes. En la Evaluación 3 aprendimos a diseñar el programa completo de una materia. Ahora, en esta evaluación final, vamos a <strong>fusionar todo</strong> con la herramienta más poderosa de un profesional de la informática: <strong>el software</strong>.</p><p>El Software Educativo no es cualquier programa que se use en una escuela. Es un sistema informático <strong>diseñado deliberadamente</strong> con un objetivo pedagógico: facilitar, apoyar o potenciar un proceso de enseñanza-aprendizaje específico. Un videojuego comercial puede enseñarte algo por accidente; un software educativo te enseña <strong>por diseño</strong>.</p><p>Este manual te guiará desde la clasificación teórica de los tipos de software educativo hasta la producción de un prototipo funcional, utilizando modelos de diseño instruccional como arquitectura y herramientas de prototipado como medio de construcción.</p><hr><h2 id="🏛️-capitulo-i-tipos-de-software-educativo" tabindex="-1">🏛️ CAPÍTULO I: Tipos de Software Educativo <a class="header-anchor" href="#🏛️-capitulo-i-tipos-de-software-educativo" aria-label="Permalink to &quot;🏛️ CAPÍTULO I: Tipos de Software Educativo&quot;">​</a></h2><h3 id="_1-1-clasificacion-general" tabindex="-1">1.1 Clasificación General <a class="header-anchor" href="#_1-1-clasificacion-general" aria-label="Permalink to &quot;1.1 Clasificación General&quot;">​</a></h3><p>No todos los programas educativos funcionan igual. Su diseño depende de la teoría de aprendizaje que los sustenta, el nivel de interacción que ofrecen y el rol que asignan al estudiante:</p><table tabindex="0"><thead><tr><th>Tipo</th><th>Descripción</th><th>Teoría Base</th><th>Ejemplo</th></tr></thead><tbody><tr><td><strong>Tutorial</strong></td><td>Presenta información de forma secuencial y guiada, simulando un tutor humano. El alumno avanza por pantallas con explicaciones, ejemplos y ejercicios.</td><td>Cognitivismo</td><td>Un curso paso a paso sobre HTML con explicaciones y prácticas guiadas.</td></tr><tr><td><strong>Drill &amp; Practice</strong></td><td>Ejercitación repetitiva. El alumno resuelve ejercicios de un mismo tipo para reforzar una habilidad específica mediante la práctica masiva.</td><td>Conductismo</td><td>Una app de tablas de multiplicar con retroalimentación inmediata.</td></tr><tr><td><strong>Simulador</strong></td><td>Reproduce un sistema real (o simplificado) donde el alumno experimenta, toma decisiones y observa las consecuencias.</td><td>Constructivismo</td><td>Un simulador de circuitos eléctricos, un laboratorio virtual de química.</td></tr><tr><td><strong>Juego Educativo</strong></td><td>Incorpora mecánicas de juego (puntos, niveles, desafíos) para motivar el aprendizaje. Combinan entretenimiento con contenido pedagógico.</td><td>Conductismo + Constructivismo</td><td>Duolingo (idiomas), Kahoot (evaluación gamificada).</td></tr><tr><td><strong>Sistema Tutor Inteligente (ITS)</strong></td><td>Software avanzado que se adapta al nivel del alumno usando algoritmos de inteligencia artificial. Detecta errores, ajusta dificultad y personaliza la ruta de aprendizaje.</td><td>Cognitivismo + IA</td><td>Plataformas adaptativas como Khan Academy o Carnegie Learning.</td></tr><tr><td><strong>Herramienta de Autoría</strong></td><td>No enseña directamente, sino que permite al docente o diseñador crear sus propios materiales educativos digitales.</td><td>N/A (meta-herramienta)</td><td>H5P, eXeLearning, Articulate Storyline.</td></tr><tr><td><strong>Entorno de Programación Educativa</strong></td><td>Lenguajes y entornos diseñados para que el alumno aprenda a programar construyendo proyectos.</td><td>Constructivismo (Papert)</td><td>Scratch, Logo, App Inventor, Blockly.</td></tr></tbody></table>',13)),(a(),i(s,null,{default:e(()=>[n(r,{id:"mermaid-150",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20SE%5B%22%F0%9F%92%BB%20Software%20Educativo%22%5D%20--%3E%20T%5B%22%F0%9F%93%96%20Tutorial%22%5D%0A%20%20%20%20SE%20--%3E%20DP%5B%22%F0%9F%94%84%20Drill%20%26%20Practice%22%5D%0A%20%20%20%20SE%20--%3E%20SIM%5B%22%F0%9F%A7%AA%20Simulador%22%5D%0A%20%20%20%20SE%20--%3E%20JE%5B%22%F0%9F%8E%AE%20Juego%20Educativo%22%5D%0A%20%20%20%20SE%20--%3E%20ITS%5B%22%F0%9F%A4%96%20Sistema%20Tutor%20Inteligente%22%5D%0A%20%20%20%20SE%20--%3E%20HA%5B%22%F0%9F%9B%A0%EF%B8%8F%20Herramienta%20de%20Autor%C3%ADa%22%5D%0A%20%20%20%20SE%20--%3E%20EPE%5B%22%F0%9F%A7%A9%20Entorno%20de%20Programaci%C3%B3n%22%5D%0A%0A%20%20%20%20style%20SE%20fill%3A%230066ff%2Cstroke%3A%230044cc%2Ccolor%3A%23fff%0A%20%20%20%20style%20T%20fill%3A%231a1a2e%2Cstroke%3A%2300d2ff%2Ccolor%3A%23e0e0e0%0A%20%20%20%20style%20DP%20fill%3A%231a1a2e%2Cstroke%3A%2300d2ff%2Ccolor%3A%23e0e0e0%0A%20%20%20%20style%20SIM%20fill%3A%231a1a2e%2Cstroke%3A%2300ff88%2Ccolor%3A%23e0e0e0%0A%20%20%20%20style%20JE%20fill%3A%231a1a2e%2Cstroke%3A%2300ff88%2Ccolor%3A%23e0e0e0%0A%20%20%20%20style%20ITS%20fill%3A%231a1a2e%2Cstroke%3A%23ff9f43%2Ccolor%3A%23e0e0e0%0A%20%20%20%20style%20HA%20fill%3A%231a1a2e%2Cstroke%3A%23ff6b6b%2Ccolor%3A%23e0e0e0%0A%20%20%20%20style%20EPE%20fill%3A%231a1a2e%2Cstroke%3A%23ff6b6b%2Ccolor%3A%23e0e0e0%0A"})]),fallback:e(()=>[...t[0]||(t[0]=[d(" Loading... ",-1)])]),_:1})),t[5]||(t[5]=o('<h3 id="_1-2-caracteristicas-de-un-buen-software-educativo" tabindex="-1">1.2 Características de un Buen Software Educativo <a class="header-anchor" href="#_1-2-caracteristicas-de-un-buen-software-educativo" aria-label="Permalink to &quot;1.2 Características de un Buen Software Educativo&quot;">​</a></h3><p>Independientemente del tipo, todo software educativo de calidad debe cumplir:</p><table tabindex="0"><thead><tr><th>Característica</th><th>Descripción</th></tr></thead><tbody><tr><td><strong>Objetivo pedagógico claro</strong></td><td>Sabe exactamente qué quiere que el alumno aprenda.</td></tr><tr><td><strong>Interactividad</strong></td><td>El alumno no solo observa; participa, decide, practica.</td></tr><tr><td><strong>Retroalimentación</strong></td><td>Informa al alumno sobre sus aciertos y errores de forma inmediata.</td></tr><tr><td><strong>Adaptabilidad</strong></td><td>Se ajusta (o permite ajustar) al ritmo y nivel del alumno.</td></tr><tr><td><strong>Usabilidad</strong></td><td>Es intuitivo, fácil de usar, con una interfaz clara y bien diseñada.</td></tr><tr><td><strong>Motivación</strong></td><td>Mantiene el interés del alumno (mediante narrativa, gamificación, retos).</td></tr><tr><td><strong>Evaluación integrada</strong></td><td>Incluye mecanismos para medir el progreso del alumno.</td></tr></tbody></table><hr><h2 id="🧩-capitulo-ii-modelos-de-diseno-instruccional-para-software-educativo" tabindex="-1">🧩 CAPÍTULO II: Modelos de Diseño Instruccional para Software Educativo <a class="header-anchor" href="#🧩-capitulo-ii-modelos-de-diseno-instruccional-para-software-educativo" aria-label="Permalink to &quot;🧩 CAPÍTULO II: Modelos de Diseño Instruccional para Software Educativo&quot;">​</a></h2><p>Crear software educativo no es simplemente &quot;programar una pantalla con botones&quot;. Requiere una metodología que combine la ingeniería de software con el diseño instruccional. Estos son los modelos más importantes:</p><h3 id="_2-1-modelo-addie-el-estandar-de-oro" tabindex="-1">2.1 Modelo ADDIE (El Estándar de Oro) <a class="header-anchor" href="#_2-1-modelo-addie-el-estandar-de-oro" aria-label="Permalink to &quot;2.1 Modelo ADDIE (El Estándar de Oro)&quot;">​</a></h3><p>ADDIE es el acrónimo de sus 5 fases. Es el modelo más utilizado en el mundo para diseñar experiencias de aprendizaje, incluyendo software educativo.</p>',8)),(a(),i(s,null,{default:e(()=>[n(r,{id:"mermaid-240",class:"mermaid",graph:"graph%20LR%0A%20%20%20%20A%5B%22%F0%9F%94%8D%20An%C3%A1lisis%22%5D%20--%3E%20D1%5B%22%F0%9F%93%90%20Dise%C3%B1o%22%5D%0A%20%20%20%20D1%20--%3E%20D2%5B%22%F0%9F%8F%97%EF%B8%8F%20Desarrollo%22%5D%0A%20%20%20%20D2%20--%3E%20I%5B%22%F0%9F%9A%80%20Implementaci%C3%B3n%22%5D%0A%20%20%20%20I%20--%3E%20E%5B%22%F0%9F%93%8A%20Evaluaci%C3%B3n%22%5D%0A%20%20%20%20E%20-.-%3E%7C%22Retroalimentaci%C3%B3n%22%7C%20A%0A%0A%20%20%20%20style%20A%20fill%3A%231a1a2e%2Cstroke%3A%23ff6b6b%2Ccolor%3A%23e0e0e0%0A%20%20%20%20style%20D1%20fill%3A%231a1a2e%2Cstroke%3A%23ff9f43%2Ccolor%3A%23e0e0e0%0A%20%20%20%20style%20D2%20fill%3A%231a1a2e%2Cstroke%3A%23feca57%2Ccolor%3A%23e0e0e0%0A%20%20%20%20style%20I%20fill%3A%231a1a2e%2Cstroke%3A%2300ff88%2Ccolor%3A%23e0e0e0%0A%20%20%20%20style%20E%20fill%3A%230066ff%2Cstroke%3A%230044cc%2Ccolor%3A%23fff%0A"})]),fallback:e(()=>[...t[1]||(t[1]=[d(" Loading... ",-1)])]),_:1})),t[6]||(t[6]=o('<table tabindex="0"><thead><tr><th>Fase</th><th>Propósito</th><th>Preguntas Clave</th><th>Producto</th></tr></thead><tbody><tr><td><strong>Análisis</strong></td><td>Entender el problema educativo.</td><td>¿Quiénes son los alumnos? ¿Qué necesitan aprender? ¿Qué recursos hay?</td><td>Documento de necesidades, perfil del usuario.</td></tr><tr><td><strong>Diseño</strong></td><td>Planificar la solución pedagógica y técnica.</td><td>¿Qué objetivos tendrá? ¿Qué estructura? ¿Qué tipo de software?</td><td>Guion instruccional, storyboard, mapa de navegación.</td></tr><tr><td><strong>Desarrollo</strong></td><td>Construir el software.</td><td>¿Con qué tecnología? ¿Quién programa? ¿Quién crea el contenido?</td><td>Prototipo funcional, código fuente, contenido multimedia.</td></tr><tr><td><strong>Implementación</strong></td><td>Poner el software en manos de los usuarios reales.</td><td>¿Cómo se distribuye? ¿Necesita capacitación?</td><td>Software desplegado, guía de usuario.</td></tr><tr><td><strong>Evaluación</strong></td><td>Medir la efectividad del software.</td><td>¿Los alumnos aprendieron? ¿La experiencia fue satisfactoria?</td><td>Informe de evaluación, métricas de uso, encuestas.</td></tr></tbody></table><h3 id="_2-2-modelo-sam-successive-approximation-model" tabindex="-1">2.2 Modelo SAM (Successive Approximation Model) <a class="header-anchor" href="#_2-2-modelo-sam-successive-approximation-model" aria-label="Permalink to &quot;2.2 Modelo SAM (Successive Approximation Model)&quot;">​</a></h3><p>Si ADDIE es el modelo &quot;en cascada&quot; (lineal y secuencial), SAM es el modelo &quot;ágil&quot;. Fue creado por Michael Allen como alternativa para proyectos donde se necesita velocidad, flexibilidad y prototipado rápido.</p>',3)),(a(),i(s,null,{default:e(()=>[n(r,{id:"mermaid-337",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20P%5B%22%F0%9F%A7%A0%20Preparaci%C3%B3n%22%5D%20--%3E%20D%5B%22%F0%9F%93%90%20Dise%C3%B1o%20Iterativo%22%5D%0A%20%20%20%20D%20--%3E%20PR%5B%22%F0%9F%94%A8%20Prototipo%22%5D%0A%20%20%20%20PR%20--%3E%20EV%5B%22%F0%9F%94%8D%20Evaluaci%C3%B3n%22%5D%0A%20%20%20%20EV%20--%3E%7C%22Iterar%22%7C%20D%0A%0A%20%20%20%20style%20P%20fill%3A%231a1a2e%2Cstroke%3A%2300d2ff%2Ccolor%3A%23e0e0e0%0A%20%20%20%20style%20D%20fill%3A%231a1a2e%2Cstroke%3A%2300ff88%2Ccolor%3A%23e0e0e0%0A%20%20%20%20style%20PR%20fill%3A%231a1a2e%2Cstroke%3A%23ff9f43%2Ccolor%3A%23e0e0e0%0A%20%20%20%20style%20EV%20fill%3A%230066ff%2Cstroke%3A%230044cc%2Ccolor%3A%23fff%0A"})]),fallback:e(()=>[...t[2]||(t[2]=[d(" Loading... ",-1)])]),_:1})),t[7]||(t[7]=o('<p><strong>Diferencias clave con ADDIE:</strong></p><table tabindex="0"><thead><tr><th>Aspecto</th><th>ADDIE</th><th>SAM</th></tr></thead><tbody><tr><td><strong>Filosofía</strong></td><td>Planificar todo antes de construir</td><td>Construir rápido, evaluar, iterar</td></tr><tr><td><strong>Velocidad</strong></td><td>Lento pero exhaustivo</td><td>Rápido, entregas incrementales</td></tr><tr><td><strong>Riesgo</strong></td><td>Se descubren problemas tarde (en implementación)</td><td>Se descubren temprano (en los prototipos)</td></tr><tr><td><strong>Ideal para</strong></td><td>Proyectos grandes, formales, corporativos</td><td>Proyectos ágiles, startups, equipos pequeños</td></tr><tr><td><strong>Prototipos</strong></td><td>Se construyen al final</td><td>Se construyen desde el principio</td></tr></tbody></table><h3 id="_2-3-modelo-assure" tabindex="-1">2.3 Modelo ASSURE <a class="header-anchor" href="#_2-3-modelo-assure" aria-label="Permalink to &quot;2.3 Modelo ASSURE&quot;">​</a></h3><p>Diseñado específicamente para integrar <strong>medios y tecnología</strong> en el aula. Es ideal cuando el docente es el actor principal y usa el software como apoyo.</p><table tabindex="0"><thead><tr><th>Letra</th><th>Fase</th><th>Descripción</th></tr></thead><tbody><tr><td><strong>A</strong></td><td>Analyze learners</td><td>Analizar las características del estudiante (edad, nivel, estilos de aprendizaje).</td></tr><tr><td><strong>S</strong></td><td>State objectives</td><td>Establecer objetivos de aprendizaje (con verbos de Bloom).</td></tr><tr><td><strong>S</strong></td><td>Select media and materials</td><td>Seleccionar los medios, tecnologías y materiales más adecuados.</td></tr><tr><td><strong>U</strong></td><td>Utilize media</td><td>Usar los materiales en clase de forma planificada.</td></tr><tr><td><strong>R</strong></td><td>Require learner participation</td><td>Exigir la participación activa del alumno.</td></tr><tr><td><strong>E</strong></td><td>Evaluate and revise</td><td>Evaluar los resultados y revisar el diseño para mejorar.</td></tr></tbody></table><hr><h2 id="🎬-capitulo-iii-el-storyboard-—-de-la-pedagogia-al-diseno-visual" tabindex="-1">🎬 CAPÍTULO III: El Storyboard — De la Pedagogía al Diseño Visual <a class="header-anchor" href="#🎬-capitulo-iii-el-storyboard-—-de-la-pedagogia-al-diseno-visual" aria-label="Permalink to &quot;🎬 CAPÍTULO III: El Storyboard — De la Pedagogía al Diseño Visual&quot;">​</a></h2><h3 id="_3-1-¿que-es-un-storyboard-educativo" tabindex="-1">3.1 ¿Qué es un Storyboard Educativo? <a class="header-anchor" href="#_3-1-¿que-es-un-storyboard-educativo" aria-label="Permalink to &quot;3.1 ¿Qué es un Storyboard Educativo?&quot;">​</a></h3><p>Un storyboard es un <strong>guion visual pantalla por pantalla</strong> que describe qué verá y hará el usuario en cada momento del software educativo. Es el puente entre el diseño instruccional (qué se enseña) y el desarrollo técnico (cómo se programa).</p><p>Antes de escribir una sola línea de código, el storyboard responde:</p><ul><li>¿Qué texto aparece en cada pantalla?</li><li>¿Qué imagen, video o animación acompaña el contenido?</li><li>¿Qué debe hacer el usuario? (Botones, campos de texto, selecciones).</li><li>¿Qué sucede si el usuario responde correctamente? ¿Y si se equivoca?</li><li>¿Hacia dónde navega después?</li></ul><h3 id="_3-2-estructura-de-un-storyboard-plantilla-por-pantalla" tabindex="-1">3.2 Estructura de un Storyboard (Plantilla por Pantalla) <a class="header-anchor" href="#_3-2-estructura-de-un-storyboard-plantilla-por-pantalla" aria-label="Permalink to &quot;3.2 Estructura de un Storyboard (Plantilla por Pantalla)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Campo</th><th>Contenido</th></tr></thead><tbody><tr><td><strong>Nº de Pantalla</strong></td><td>Identificador único (ej. P-001, P-002).</td></tr><tr><td><strong>Título de la Pantalla</strong></td><td>Nombre descriptivo (ej. &quot;Introducción al tema&quot;).</td></tr><tr><td><strong>Evento de Gagné</strong></td><td>¿A qué evento de instrucción corresponde esta pantalla?</td></tr><tr><td><strong>Texto en pantalla</strong></td><td>El contenido textual exacto que verá el usuario.</td></tr><tr><td><strong>Elementos multimedia</strong></td><td>Imagen, video, audio o animación a incluir.</td></tr><tr><td><strong>Interacción del usuario</strong></td><td>¿Qué acción realiza el usuario? (Clic, arrastrar, escribir, seleccionar).</td></tr><tr><td><strong>Retroalimentación</strong></td><td>¿Qué pasa si responde bien? ¿Y si responde mal?</td></tr><tr><td><strong>Navegación</strong></td><td>¿A qué pantalla va después? (Lineal, ramificada, libre).</td></tr></tbody></table><h3 id="_3-3-ejemplo-storyboard-para-un-tutorial-sobre-modelo-osi" tabindex="-1">3.3 Ejemplo: Storyboard para un Tutorial sobre &quot;Modelo OSI&quot; <a class="header-anchor" href="#_3-3-ejemplo-storyboard-para-un-tutorial-sobre-modelo-osi" aria-label="Permalink to &quot;3.3 Ejemplo: Storyboard para un Tutorial sobre &quot;Modelo OSI&quot;&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Pantalla</th><th>Evento Gagné</th><th>Contenido</th><th>Interacción</th></tr></thead><tbody><tr><td><strong>P-001</strong></td><td>1. Ganar atención</td><td>Video animado de 30 seg: &quot;¿Cómo viaja un correo electrónico de tu PC a otra al otro lado del mundo?&quot;</td><td>Botón &quot;Comenzar&quot;</td></tr><tr><td><strong>P-002</strong></td><td>2. Objetivos</td><td>&quot;Al finalizar este módulo, serás capaz de nombrar las 7 capas del modelo OSI y describir la función de cada una.&quot;</td><td>Botón &quot;Siguiente&quot;</td></tr><tr><td><strong>P-003</strong></td><td>3. Conocimientos previos</td><td>&quot;Antes de empezar, ¿sabes qué es un protocolo de red? Selecciona tu respuesta:&quot; [Sí / No / No estoy seguro]</td><td>Selección múltiple</td></tr><tr><td><strong>P-004</strong></td><td>4. Contenido</td><td>Infografía interactiva: Diagrama de las 7 capas. Al hacer clic en cada capa, se despliega su descripción y función.</td><td>Clic en cada capa</td></tr><tr><td><strong>P-005</strong></td><td>5. Guía</td><td>Analogía visual: &quot;Piensa en las capas OSI como el proceso de enviar una carta por correo postal...&quot; con imagen comparativa.</td><td>Scroll</td></tr><tr><td><strong>P-006</strong></td><td>6. Práctica</td><td>Ejercicio de arrastrar y soltar: Ordenar las 7 capas del modelo OSI de arriba hacia abajo.</td><td>Drag &amp; Drop</td></tr><tr><td><strong>P-007</strong></td><td>7. Retroalimentación</td><td>Si correcto: &quot;✅ ¡Excelente! El orden es perfecto.&quot; / Si incorrecto: &quot;❌ Casi. Recuerda: la capa Física está abajo y la de Aplicación arriba.&quot;</td><td>Automática</td></tr><tr><td><strong>P-008</strong></td><td>8. Evaluación</td><td>Quiz de 5 preguntas de selección múltiple sobre las capas y sus funciones.</td><td>Selección múltiple</td></tr><tr><td><strong>P-009</strong></td><td>9. Transferencia</td><td>&quot;Ahora que conoces las capas OSI, investiga: ¿en qué capa opera un Switch? ¿Y un Router? Anota tus respuestas para la próxima sesión.&quot;</td><td>Botón &quot;Finalizar&quot;</td></tr></tbody></table><hr><h2 id="🏗️-capitulo-iv-herramientas-para-producir-un-prototipo" tabindex="-1">🏗️ CAPÍTULO IV: Herramientas para Producir un Prototipo <a class="header-anchor" href="#🏗️-capitulo-iv-herramientas-para-producir-un-prototipo" aria-label="Permalink to &quot;🏗️ CAPÍTULO IV: Herramientas para Producir un Prototipo&quot;">​</a></h2><h3 id="_4-1-niveles-de-prototipado" tabindex="-1">4.1 Niveles de Prototipado <a class="header-anchor" href="#_4-1-niveles-de-prototipado" aria-label="Permalink to &quot;4.1 Niveles de Prototipado&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Nivel</th><th>Descripción</th><th>Herramientas</th></tr></thead><tbody><tr><td><strong>Baja fidelidad</strong></td><td>Bocetos en papel, wireframes simples. Rápidos de crear, ideales para validar la estructura.</td><td>Papel y lápiz, Balsamiq, Whimsical.</td></tr><tr><td><strong>Media fidelidad</strong></td><td>Mockups digitales con diseño visual pero sin funcionalidad real.</td><td>Figma, Canva, PowerPoint, Google Slides.</td></tr><tr><td><strong>Alta fidelidad</strong></td><td>Prototipos interactivos y funcionales. El usuario puede hacer clic, navegar y completar actividades.</td><td>HTML/CSS/JS, Scratch, H5P, eXeLearning.</td></tr></tbody></table><h3 id="_4-2-herramientas-recomendadas-para-prototipos-funcionales" tabindex="-1">4.2 Herramientas Recomendadas para Prototipos Funcionales <a class="header-anchor" href="#_4-2-herramientas-recomendadas-para-prototipos-funcionales" aria-label="Permalink to &quot;4.2 Herramientas Recomendadas para Prototipos Funcionales&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Herramienta</th><th>Tipo</th><th>Ventaja Principal</th><th>Ideal Para</th></tr></thead><tbody><tr><td><strong>PowerPoint / Google Slides</strong></td><td>Presentación interactiva</td><td>Fácil de usar, hipervínculos entre diapositivas simulan navegación.</td><td>Prototipos rápidos de baja-media fidelidad.</td></tr><tr><td><strong>Canva</strong></td><td>Diseño visual</td><td>Plantillas profesionales, fácil de compartir.</td><td>Storyboards visuales y prototipos estáticos.</td></tr><tr><td><strong>H5P</strong></td><td>Contenido interactivo web</td><td>Crea actividades interactivas (quizzes, drag &amp; drop, videos interactivos) sin programar.</td><td>Actividades embebibles en LMS (Moodle).</td></tr><tr><td><strong>eXeLearning</strong></td><td>Autor de contenido educativo</td><td>Software libre, exporta a HTML y SCORM. Diseñado específicamente para educación.</td><td>Prototipos educativos completos y exportables.</td></tr><tr><td><strong>Scratch</strong></td><td>Programación visual</td><td>Bloques de código visual. Permite crear juegos y tutoriales interactivos sin código textual.</td><td>Juegos educativos y simulaciones simples.</td></tr><tr><td><strong>HTML + CSS + JavaScript</strong></td><td>Desarrollo web</td><td>Control total, funcionalidad real, desplegable en cualquier navegador.</td><td>Prototipos de alta fidelidad para desarrolladores.</td></tr></tbody></table><h3 id="_4-3-ciclo-de-vida-del-prototipo-educativo" tabindex="-1">4.3 Ciclo de Vida del Prototipo Educativo <a class="header-anchor" href="#_4-3-ciclo-de-vida-del-prototipo-educativo" aria-label="Permalink to &quot;4.3 Ciclo de Vida del Prototipo Educativo&quot;">​</a></h3>',22)),(a(),i(s,null,{default:e(()=>[n(r,{id:"mermaid-939",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20A%5B%221.%20Definir%20objetivo%20pedag%C3%B3gico%22%5D%20--%3E%20B%5B%222.%20Crear%20Storyboard%22%5D%0A%20%20%20%20B%20--%3E%20C%5B%223.%20Dise%C3%B1ar%20interfaz%20(mockup)%22%5D%0A%20%20%20%20C%20--%3E%20D%5B%224.%20Desarrollar%20prototipo%20funcional%22%5D%0A%20%20%20%20D%20--%3E%20E%5B%225.%20Probar%20con%20usuarios%20reales%22%5D%0A%20%20%20%20E%20--%3E%20F%7B%7B%22%C2%BFCumple%20el%20objetivo%3F%22%7D%7D%0A%20%20%20%20F%20--%20%22S%C3%AD%22%20--%3E%20G%5B%226.%20Documentar%20y%20presentar%22%5D%0A%20%20%20%20F%20--%20%22No%22%20--%3E%20B%0A%0A%20%20%20%20style%20A%20fill%3A%231a1a2e%2Cstroke%3A%2300d2ff%2Ccolor%3A%23e0e0e0%0A%20%20%20%20style%20B%20fill%3A%231a1a2e%2Cstroke%3A%2300d2ff%2Ccolor%3A%23e0e0e0%0A%20%20%20%20style%20C%20fill%3A%231a1a2e%2Cstroke%3A%2300ff88%2Ccolor%3A%23e0e0e0%0A%20%20%20%20style%20D%20fill%3A%231a1a2e%2Cstroke%3A%2300ff88%2Ccolor%3A%23e0e0e0%0A%20%20%20%20style%20E%20fill%3A%231a1a2e%2Cstroke%3A%23ff9f43%2Ccolor%3A%23e0e0e0%0A%20%20%20%20style%20F%20fill%3A%231a1a2e%2Cstroke%3A%23ffaa00%2Ccolor%3A%23e0e0e0%0A%20%20%20%20style%20G%20fill%3A%230066ff%2Cstroke%3A%230044cc%2Ccolor%3A%23fff%0A"})]),fallback:e(()=>[...t[3]||(t[3]=[d(" Loading... ",-1)])]),_:1})),t[8]||(t[8]=o('<hr><h2 id="🧪-capitulo-v-guia-para-el-proyecto-final" tabindex="-1">🧪 CAPÍTULO V: Guía para el Proyecto Final <a class="header-anchor" href="#🧪-capitulo-v-guia-para-el-proyecto-final" aria-label="Permalink to &quot;🧪 CAPÍTULO V: Guía para el Proyecto Final&quot;">​</a></h2><h3 id="requisitos-del-prototipo" tabindex="-1">Requisitos del Prototipo <a class="header-anchor" href="#requisitos-del-prototipo" aria-label="Permalink to &quot;Requisitos del Prototipo&quot;">​</a></h3><p>Tu proyecto final consiste en producir un <strong>prototipo funcional de software educativo</strong> sobre un tema de tu elección (preferiblemente relacionado con el PNFI). El prototipo debe cumplir los siguientes requisitos mínimos:</p><table tabindex="0"><thead><tr><th>Requisito</th><th>Detalle</th></tr></thead><tbody><tr><td><strong>Tema definido</strong></td><td>Un tema específico y delimitado (no &quot;Redes&quot; en general, sino &quot;Direcciones IPv4 y sus clases&quot;).</td></tr><tr><td><strong>Objetivo de aprendizaje</strong></td><td>Al menos 1 objetivo claro redactado con la Taxonomía de Bloom.</td></tr><tr><td><strong>Eventos de Gagné</strong></td><td>Debe incorporar al menos 5 de los 9 eventos de instrucción.</td></tr><tr><td><strong>Interactividad</strong></td><td>Al menos 1 actividad donde el usuario participe activamente (quiz, drag &amp; drop, ejercicio).</td></tr><tr><td><strong>Retroalimentación</strong></td><td>El software debe informar al usuario si su respuesta es correcta o incorrecta.</td></tr><tr><td><strong>Storyboard</strong></td><td>Entregar el storyboard escrito (pantalla por pantalla) junto con el prototipo.</td></tr><tr><td><strong>Herramienta</strong></td><td>Libre elección (PowerPoint, H5P, Scratch, HTML/CSS/JS, eXeLearning, etc.).</td></tr></tbody></table><h3 id="rubrica-de-evaluacion-sugerida" tabindex="-1">Rúbrica de Evaluación Sugerida <a class="header-anchor" href="#rubrica-de-evaluacion-sugerida" aria-label="Permalink to &quot;Rúbrica de Evaluación Sugerida&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Criterio</th><th>Excelente (5)</th><th>Bueno (4)</th><th>Regular (3)</th><th>Deficiente (1-2)</th></tr></thead><tbody><tr><td><strong>Objetivo pedagógico</strong></td><td>Claro, medible, con verbo de Bloom</td><td>Claro pero sin verbo preciso</td><td>Vago o genérico</td><td>Ausente</td></tr><tr><td><strong>Eventos de Gagné</strong></td><td>7-9 eventos incorporados</td><td>5-6 eventos</td><td>3-4 eventos</td><td>Menos de 3</td></tr><tr><td><strong>Interactividad</strong></td><td>Múltiples actividades participativas</td><td>Al menos 1 actividad</td><td>Interacción mínima (solo botones de navegación)</td><td>Sin interacción</td></tr><tr><td><strong>Retroalimentación</strong></td><td>Inmediata, específica y constructiva</td><td>Presente pero genérica</td><td>Solo &quot;correcto/incorrecto&quot;</td><td>Ausente</td></tr><tr><td><strong>Diseño visual</strong></td><td>Profesional, limpio, coherente</td><td>Aceptable, organizado</td><td>Desorganizado o poco legible</td><td>Ilegible o caótico</td></tr><tr><td><strong>Storyboard</strong></td><td>Completo, detallado, alineado con Gagné</td><td>Completo pero sin vincular a Gagné</td><td>Incompleto</td><td>Ausente</td></tr></tbody></table><hr><h2 id="📘-anexo-diccionario-tecnico-formal" tabindex="-1">📘 ANEXO: Diccionario Técnico Formal <a class="header-anchor" href="#📘-anexo-diccionario-tecnico-formal" aria-label="Permalink to &quot;📘 ANEXO: Diccionario Técnico Formal&quot;">​</a></h2><ul><li><strong>Software Educativo:</strong> Sistema informático diseñado deliberadamente con fundamento pedagógico para facilitar, apoyar o automatizar un proceso de enseñanza-aprendizaje específico.</li><li><strong>Tutorial (tipo de software):</strong> Programa que simula un tutor humano, presentando información de forma secuencial y guiada con ejercicios intercalados.</li><li><strong>Drill &amp; Practice:</strong> Tipo de software enfocado en la ejercitación repetitiva de una habilidad mediante ensayo y error con retroalimentación inmediata.</li><li><strong>Simulador Educativo:</strong> Software que reproduce un sistema o fenómeno real (simplificado) permitiendo al usuario experimentar, explorar y observar consecuencias sin riesgo.</li><li><strong>Gamificación:</strong> Aplicación de mecánicas y dinámicas propias de los juegos (puntos, niveles, insignias, competencia) en contextos no lúdicos para incrementar la motivación y el compromiso.</li><li><strong>Modelo ADDIE:</strong> Marco metodológico de diseño instruccional compuesto por cinco fases secuenciales: Análisis, Diseño, Desarrollo, Implementación y Evaluación.</li><li><strong>Modelo SAM:</strong> Modelo de diseño instruccional iterativo basado en aproximaciones sucesivas y prototipado rápido, alternativa ágil al modelo ADDIE lineal.</li><li><strong>Modelo ASSURE:</strong> Marco de integración tecnológica en el aula que guía al docente en el análisis del estudiante, la selección de medios, la participación activa y la evaluación de resultados.</li><li><strong>Storyboard Educativo:</strong> Guion visual que describe pantalla por pantalla el contenido, la interacción, la retroalimentación y la navegación de un software o material educativo digital.</li><li><strong>Prototipo:</strong> Versión preliminar y funcional de un producto de software que permite validar su diseño, usabilidad y efectividad antes de la versión final.</li><li><strong>Herramienta de Autoría:</strong> Software que permite a usuarios no programadores crear contenido educativo digital interactivo mediante interfaces gráficas y plantillas prediseñadas.</li><li><strong>SCORM (Sharable Content Object Reference Model):</strong> Estándar técnico que permite la interoperabilidad de contenidos educativos digitales entre diferentes plataformas LMS.</li><li><strong>Usabilidad:</strong> Grado en que un producto de software puede ser utilizado por usuarios específicos para lograr objetivos concretos con eficacia, eficiencia y satisfacción.</li></ul>',10))])}const C=l(p,[["render",m]]);export{E as __pageData,C as default};
